const { withDangerousMod, withInfoPlist, withXcodeProject } = require("expo/config-plugins");
const fs = require("fs");
const path = require("path");

/**
 * Injects the iOS WidgetKit extension during prebuild. The native dirs are gitignored
 * and regenerated by `expo prebuild`, so the canonical Swift/Info.plist/entitlements
 * live in the tracked `widget/ios/VeloqWidget/` tree. This plugin:
 *   1. copies that tree into ios/VeloqWidget/
 *   2. adds a `VeloqWidget` app-extension target to the Xcode project, wires the Swift
 *      files into its Sources phase, sets the bundle id / Info.plist / entitlements /
 *      deployment target, and depends the app target on it.
 *
 * `addTarget('app_extension', …)` from cordova-node-xcode already creates the product,
 * the embed (Copy Files) phase in the app target, and a default build-config list, so
 * this only fills in the phases, the source files, and the extension-specific settings.
 *
 * The App Group entitlement on both the app and this extension is added by
 * with-app-groups.js. Signing (team, App Group capability) is resolved by Xcode/EAS at
 * build time, the same way the existing iCloud capability is.
 */

const { INCLUDE_RECORD_WIDGET } = require("./widgetFlags");

const TARGET = "VeloqWidget";

/**
 * The Live Activity contract. ActivityKit matches a card to its attributes by type
 * name, so the app process and the extension have to compile the same declaration.
 * These two files are tracked once under widget/ios and copied into the bridge
 * module at prebuild; the views alongside them stay extension-only, they import
 * WidgetKit and would not build in the app.
 */
const LIVE_ACTIVITY_SHARED_FILES = [
  "RecordingActivityAttributes.swift",
  "RecordingActivityIntents.swift",
];

const LIVE_ACTIVITY_MODULE_DIR = path.join("modules", "veloq-live-activity", "ios");

/**
 * Swift compiled by BOTH the app and the widget extension, from
 * `widget/ios/shared/`. `AppShortcutsProvider` has to be in the app target for
 * Siri and Shortcuts to surface the phrase, and the deep-link rule it uses is
 * the extension's too, so one file goes to both rather than two files drifting.
 */
const SHARED_DIR = path.join("widget", "ios", "shared");
const SHARED_APP_FILES = ["RecordDeepLink.swift", "VeloqAppShortcuts.swift"];

function copySharedLiveActivitySources(srcDir, destDir) {
  fs.mkdirSync(destDir, { recursive: true });
  for (const name of LIVE_ACTIVITY_SHARED_FILES) {
    const from = path.join(srcDir, name);
    if (fs.existsSync(from)) fs.copyFileSync(from, path.join(destDir, name));
  }
}

/**
 * Write the widget bundles, whose membership is what puts a widget in the
 * gallery. Generated rather than tracked because Quick-Record's gate is a
 * JavaScript constant the Swift cannot read, and a `WidgetBundle` body is a
 * result builder that cannot branch on one. Android drops the receiver from the
 * manifest for the same reason; this is that mechanism on iOS.
 */
const BUNDLES_FILE = "WidgetBundles.swift";

/**
 * Every Swift file the extension compiles: the tracked sources, plus the
 * bundles this plugin generates. The generated one exists only under `ios/`,
 * so a list read from `widget/ios/` alone leaves the target without the two
 * bundles `VeloqWidgetLauncher` calls `main()` on.
 */
function widgetSwiftFiles(projectRoot) {
  const tracked = fs
    .readdirSync(path.join(projectRoot, "widget", "ios", TARGET))
    .filter((f) => f.endsWith(".swift"));
  const withBundles = tracked.includes(BUNDLES_FILE) ? tracked : [...tracked, BUNDLES_FILE];
  // The extension needs the shared link rule; it does not need the App Shortcut,
  // whose provider only counts in the app target.
  return [...withBundles, "RecordDeepLink.swift"];
}

function writeWidgetBundles(destDir, includeRecord = INCLUDE_RECORD_WIDGET) {
  // The Control rides the same gate as the widget: one record surface off means
  // every record surface off. It is iOS 18 and the bundle body is not, so it is
  // gated inside the result builder, the way the Live Activity is gated at 16.2.
  const record = includeRecord
    ? `
    VeloqRecordWidget()
    if #available(iOS 18.0, *) {
      VeloqRecordControl()
    }`
    : "";
  const liveActivity = `
    if #available(iOS 16.2, *) {
      VeloqRecordingLiveActivity()
    }`;
  fs.mkdirSync(destDir, { recursive: true });
  fs.writeFileSync(
    path.join(destDir, BUNDLES_FILE),
    `// Generated by src/plugins/with-ios-widget.js. Do not edit.
import SwiftUI
import WidgetKit

struct VeloqWidgets: WidgetBundle {
  var body: some Widget {
    VeloqWidget()
    VeloqLatestActivityWidget()${record}${liveActivity}
  }
}

@available(iOS 17.0, *)
struct VeloqWidgetsConfigurable: WidgetBundle {
  var body: some Widget {
    VeloqConfigurableWidget()
    VeloqLatestActivityWidget()${record}${liveActivity}
  }
}
`
  );
}

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) copyDir(from, to);
    else fs.copyFileSync(from, to);
  }
}

/**
 * Delete files under `dest` that no longer exist under `src`. copyDir alone is
 * additive, so a resource removed from widget/ would linger in ios/.
 *
 * Swift files are deliberately left alone: the Sources build phase still
 * references them, and deleting the file without removing that reference fails
 * the Xcode build outright. Removing a Swift file from the widget therefore
 * still needs a clean prebuild (`npx expo prebuild -p ios --clean`).
 */
function pruneRemoved(src, dest) {
  if (!fs.existsSync(dest)) return;
  for (const entry of fs.readdirSync(dest, { withFileTypes: true })) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      if (fs.existsSync(from)) pruneRemoved(from, to);
      else fs.rmSync(to, { recursive: true, force: true });
    } else if (!fs.existsSync(from) && !entry.name.endsWith(".swift")) {
      fs.rmSync(to, { force: true });
    }
  }
}

function withWidgetFiles(config) {
  return withDangerousMod(config, [
    "ios",
    (cfg) => {
      const src = path.join(cfg.modRequest.projectRoot, "widget", "ios", TARGET);
      const dest = path.join(cfg.modRequest.platformProjectRoot, TARGET);
      copyDir(src, dest);
      pruneRemoved(src, dest);
      writeWidgetBundles(dest);

      // The shared files land in both target directories: the extension reads
      // its copy beside the widget sources, the app reads its own.
      const shared = path.join(cfg.modRequest.projectRoot, SHARED_DIR);
      const appDir = path.join(cfg.modRequest.platformProjectRoot, cfg.modRequest.projectName);
      fs.mkdirSync(appDir, { recursive: true });
      for (const name of SHARED_APP_FILES) {
        fs.copyFileSync(path.join(shared, name), path.join(appDir, name));
      }
      fs.copyFileSync(
        path.join(shared, "RecordDeepLink.swift"),
        path.join(dest, "RecordDeepLink.swift")
      );
      copySharedLiveActivitySources(
        src,
        path.join(cfg.modRequest.projectRoot, LIVE_ACTIVITY_MODULE_DIR)
      );
      return cfg;
    },
  ]);
}

const unquote = (v) => String(v ?? "").replace(/^"|"$/g, "");

/**
 * The uuid of a native target by name.
 *
 * Neither `findTargetKey` nor `pbxTargetByName` finds it: pbxproj stores the
 * name and the section comment quoted, and both helpers compare against the
 * bare string. That is why the old `if (proj.pbxTargetByName(TARGET)) return`
 * idempotency guard never fired, and every incremental prebuild appended
 * another copy of the widget target.
 */
function targetUuidByName(proj, name) {
  const section = proj.pbxNativeTargetSection();
  for (const key of Object.keys(section)) {
    if (!key.endsWith("_comment")) continue;
    if (unquote(section[key]) === name) return key.replace(/_comment$/, "");
  }
  return null;
}

/** Swift file names already compiled by a target, without the phase suffix. */
function compiledSourceNames(proj, targetUuid) {
  const phase = proj.pbxSourcesBuildPhaseObj(targetUuid);
  const names = new Set();
  for (const entry of phase?.files ?? []) {
    const name = unquote(String(entry.comment || "").replace(/ in Sources$/, ""));
    if (name) names.add(name);
  }
  return names;
}

/**
 * Add Swift files present on disk but missing from the target's Sources phase.
 * The target survives every prebuild after the first, so without this a file
 * added to widget/ios is copied into ios/ and then never compiled.
 */
function addMissingSourceFiles(proj, targetUuid, swiftFiles, groupName = TARGET) {
  const compiled = compiledSourceNames(proj, targetUuid);
  const missing = swiftFiles.filter((f) => !compiled.has(f));
  if (missing.length === 0) return;

  let groupUuid = proj.findPBXGroupKey({ name: groupName });
  if (!groupUuid) {
    const group = proj.addPbxGroup([], groupName, groupName);
    proj.addToPbxGroup(group.uuid, proj.getFirstProject().firstProject.mainGroup);
    groupUuid = group.uuid;
  }
  for (const file of missing) {
    proj.addSourceFile(file, { target: targetUuid }, groupUuid);
  }
}

function withWidgetTarget(config) {
  return withXcodeProject(config, (cfg) => {
    const proj = cfg.modResults;
    const swiftFiles = widgetSwiftFiles(cfg.modRequest.projectRoot);
    // The phase helpers key off the target uuid, and pbxTargetByName returns
    // the target object instead. Passing that through resolves to the FIRST
    // sources phase in the project, which belongs to the app.
    // The App Shortcut and the link rule it uses belong to the app target, and
    // the app target already exists on every prebuild, so this runs either way.
    const appTargetUuid = targetUuidByName(proj, cfg.modRequest.projectName);
    if (appTargetUuid) {
      addMissingSourceFiles(proj, appTargetUuid, SHARED_APP_FILES, cfg.modRequest.projectName);
    }

    const existingTargetUuid = targetUuidByName(proj, TARGET);
    if (existingTargetUuid) {
      addMissingSourceFiles(proj, existingTargetUuid, swiftFiles);
      return cfg;
    }

    const appBundleId = cfg.ios?.bundleIdentifier || "com.veloq.app";
    const widgetBundleId = `${appBundleId}.${TARGET}`;
    const version = cfg.version || "1.0.0";
    const buildNumber = cfg.ios?.buildNumber || "1";

    const target = proj.addTarget(TARGET, "app_extension", TARGET, widgetBundleId);

    proj.addBuildPhase([], "PBXSourcesBuildPhase", "Sources", target.uuid);
    proj.addBuildPhase([], "PBXResourcesBuildPhase", "Resources", target.uuid);
    proj.addBuildPhase([], "PBXFrameworksBuildPhase", "Frameworks", target.uuid);

    const group = proj.addPbxGroup([], TARGET, TARGET);
    const mainGroup = proj.getFirstProject().firstProject.mainGroup;
    proj.addToPbxGroup(group.uuid, mainGroup);

    for (const file of swiftFiles) {
      proj.addSourceFile(file, { target: target.uuid }, group.uuid);
    }

    const configurations = proj.pbxXCBuildConfigurationSection();
    for (const key in configurations) {
      const settings = configurations[key].buildSettings;
      if (!settings || settings.PRODUCT_NAME !== `"${TARGET}"`) continue;
      settings.INFOPLIST_FILE = `"${TARGET}/Info.plist"`;
      settings.CODE_SIGN_ENTITLEMENTS = `"${TARGET}/${TARGET}.entitlements"`;
      settings.CODE_SIGN_STYLE = "Automatic";
      // ActivityKit is 16.1 and the app's own deployment target is already 16.4
      // (expo-build-properties), so nothing could install against 15.1 anyway.
      settings.IPHONEOS_DEPLOYMENT_TARGET = '"16.4"';
      settings.SWIFT_VERSION = '"5.9"';
      settings.TARGETED_DEVICE_FAMILY = '"1,2"';
      settings.GENERATE_INFOPLIST_FILE = "NO";
      settings.CURRENT_PROJECT_VERSION = `"${buildNumber}"`;
      settings.MARKETING_VERSION = `"${version}"`;
    }

    proj.addTargetDependency(proj.getFirstTarget().uuid, [target.uuid]);
    return cfg;
  });
}

/** Without this key iOS never presents a Live Activity, and nothing says why. */
function withLiveActivitySupport(config) {
  return withInfoPlist(config, (cfg) => {
    cfg.modResults.NSSupportsLiveActivities = true;
    return cfg;
  });
}

module.exports = function withIosWidget(config) {
  config = withWidgetFiles(config);
  config = withWidgetTarget(config);
  config = withLiveActivitySupport(config);
  return config;
};

module.exports.INCLUDE_RECORD_WIDGET = INCLUDE_RECORD_WIDGET;
module.exports.writeWidgetBundles = writeWidgetBundles;
module.exports.copySharedLiveActivitySources = copySharedLiveActivitySources;
module.exports.LIVE_ACTIVITY_SHARED_FILES = LIVE_ACTIVITY_SHARED_FILES;
module.exports.widgetSwiftFiles = widgetSwiftFiles;
module.exports.BUNDLES_FILE = BUNDLES_FILE;
module.exports.SHARED_APP_FILES = SHARED_APP_FILES;
module.exports.SHARED_DIR = SHARED_DIR;
